// 1 of 10
float sdCircle(vec2 p, float r)
{
    return length(p) - r;
}

// 2 of 10
float sdBox(vec2 p, vec2 b)
{
    vec2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

// 3 of 10
float sdTriangle(vec2 p, float r)
{
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r/k;
    if( p.x+k*p.y>0.0 ) p = vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0*r, 0.0 );
    return -length(p)*sign(p.y);
}

// 4 of 10
float ndot(vec2 a, vec2 b ) { return a.x*b.x - a.y*b.y; }
float sdRhombus( in vec2 p, in vec2 b ) 
{
    p = abs(p);
    float h = clamp( ndot(b-2.0*p,b)/dot(b,b), -1.0, 1.0 );
    float d = length( p-0.5*b*vec2(1.0-h,1.0+h) );
    return d * sign( p.x*b.y + p.y*b.x - b.x*b.y );
}

// 5 of 10
float sdPentagon( in vec2 p, in float r )
{
    const vec3 k = vec3(0.809016994,0.587785252,0.726542528);
    p.x = abs(p.x);
    p -= 2.0*min(dot(vec2(-k.x,k.y),p),0.0)*vec2(-k.x,k.y);
    p -= 2.0*min(dot(vec2( k.x,k.y),p),0.0)*vec2( k.x,k.y);
    p -= vec2(clamp(p.x,-r*k.z,r*k.z),r);    
    return length(p)*sign(p.y);
}

// 6 of 10
float sdHexagon( in vec2 p, in float r )
{
    const vec3 k = vec3(-0.866025404,0.5,0.577350269);
    p = abs(p);
    p -= 2.0*min(dot(k.xy,p),0.0)*k.xy;
    p -= vec2(clamp(p.x, -k.z*r, k.z*r), r);
    return length(p)*sign(p.y);
}

// 7 of 10
float sdOctogon( in vec2 p, in float r )
{
    const vec3 k = vec3(-0.9238795325, 0.3826834323, 0.4142135623 );
    p = abs(p);
    p -= 2.0*min(dot(vec2( k.x,k.y),p),0.0)*vec2( k.x,k.y);
    p -= 2.0*min(dot(vec2(-k.x,k.y),p),0.0)*vec2(-k.x,k.y);
    p -= vec2(clamp(p.x, -k.z*r, k.z*r), r);
    return length(p)*sign(p.y);
}

// 8 of 10
float sdHexagram( in vec2 p, in float r )
{
    const vec4 k = vec4(-0.5,0.8660254038,0.5773502692,1.7320508076);
    p = abs(p);
    p -= 2.0*min(dot(k.xy,p),0.0)*k.xy;
    p -= 2.0*min(dot(k.yx,p),0.0)*k.yx;
    p -= vec2(clamp(p.x,r*k.z,r*k.w),r);
    return length(p)*sign(p.y);
}

// 9 of 10
float sdStar5(in vec2 p, in float r, in float rf)
{
    const vec2 k1 = vec2(0.809016994375, -0.587785252292);
    const vec2 k2 = vec2(-k1.x,k1.y);
    p.x = abs(p.x);
    p -= 2.0*max(dot(k1,p),0.0)*k1;
    p -= 2.0*max(dot(k2,p),0.0)*k2;
    p.x = abs(p.x);
    p.y -= r;
    vec2 ba = rf*vec2(-k1.y,k1.x) - vec2(0,1);
    float h = clamp( dot(p,ba)/dot(ba,ba), 0.0, r );
    return length(p-ba*h) * sign(p.y*ba.x-p.x*ba.y);
}

// 10 of 10! Yippee!
float sdCross( in vec2 p, in vec2 b, float r ) 
{
    p = abs(p); p = (p.y>p.x) ? p.yx : p.xy;
    vec2  q = p - b;
    float k = max(q.y,q.x);
    vec2  w = (k>0.0) ? q : vec2(b.y-p.x,-k);
    return sign(k)*length(max(w,0.0)) + r;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    float aspect = iResolution.x / iResolution.y;
    uv.x *= aspect;

    float circle = sdCircle(uv - vec2(1.5, -0.75), 0.1);
    float box = sdBox(uv - vec2(-1.5, 0.75), vec2(0.1, 0.1));
    float triangle = sdTriangle(uv, 0.1);
    float rhombus = sdRhombus(uv - vec2(-1.0, 0.75), vec2(0.12, 0.12));
    float pentagon = sdPentagon(uv - vec2(-0.5, 0.75), 0.1);
    float hexagon = sdHexagon(uv - vec2(0.8, -0.75), 0.1);
    float octagon = sdOctogon(uv - vec2(0.0, -0.75), 0.1);
    float hexagram = sdHexagram(uv - vec2(0.0, 0.75), 0.09);
    float star = sdStar5(uv - vec2(1.0, 0.0), 0.5, 0.5);
    float plus = sdCross(uv - vec2(-1.0, 0.0), vec2(0.3, 0.1), 0.05);

    // Combine two SDFs by storing their minimum (negative if inside shape)
    float shapes = min(circle, box); 

    // Combine multiple shapes by comparing the previous result with the new shape
    shapes = min(shapes, triangle);
    shapes = min(shapes, rhombus);
    shapes = min(shapes, pentagon);
    shapes = min(shapes, hexagon);
    shapes = min(shapes, octagon);
    shapes = min(shapes, hexagram);
    shapes = min(shapes, star);
    shapes = min(shapes, plus);


    // 1.0 ("true") if we're inside a shape.
    // 0.0 ("false") if we're outside a shape.
    shapes = 1.0 - step(0.0, shapes);

    // Color black if within the circle, otherwise white
    vec3 rgb = vec3(1.0, 0.0, 1.0) * shapes;

    // Write pixel colour
    fragColor = vec4(rgb, 1.0);
}
